// SPDX-License-Identifier: MIT
pragma solidity 0.8.38;
import {ProbeVault} from "../src/ProbeVault.sol";
interface Vm {
    function deal(address account, uint256 amount) external;
    function prank(address caller) external;
}
contract ProbeTest {
    Vm constant vm = Vm(address(uint160(uint256(keccak256("hevm cheat code")))));
    ProbeVault vault;
    address payable constant victim = payable(address(0x1001));
    address payable constant attacker = payable(address(0x1002));
    function setUp() public {
        vault = new ProbeVault();
        vm.deal(victim, 10 ether);
        vm.prank(victim);
        vault.deposit{value: 10 ether}();
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        vault.deposit{value: 1 ether}();
    }
    function testCrossAccountWithdrawalBlocked() public {
        vm.prank(attacker);
        (bool ok,) = address(vault).call(abi.encodeCall(vault.withdraw, (5 ether)));
        require(!ok, "attacker withdrew more than deposited");
        require(address(vault).balance == 11 ether, "pool drained");
        require(vault.balanceOf(victim) == 10 ether, "victim accounting changed");
        require(vault.balanceOf(attacker) == 1 ether, "rejected call changed balance");
    }
    function testUnfundedAccountCannotWithdraw() public {
        vm.prank(address(0x1003));
        (bool ok,) = address(vault).call(abi.encodeCall(vault.withdraw, (1 ether)));
        require(!ok, "unfunded account stole funds");
        require(address(vault).balance == 11 ether, "pool changed");
    }
    function testOwnFullWithdrawal() public {
        vm.prank(attacker);
        vault.withdraw(1 ether);
        require(attacker.balance == 1 ether, "wrong payout");
        require(vault.balanceOf(attacker) == 0, "claim not consumed");
        require(vault.balanceOf(victim) == 10 ether, "victim claim changed");
        require(address(vault).balance == 10 ether, "wrong pool balance");
    }
    function testPartialWithdrawal() public {
        vm.prank(victim);
        vault.withdraw(4 ether);
        require(victim.balance == 4 ether, "wrong payout");
        require(vault.balanceOf(victim) == 6 ether, "wrong remaining claim");
        require(vault.balanceOf(attacker) == 1 ether, "other claim changed");
        require(address(vault).balance == 7 ether, "wrong pool balance");
    }
    function testZeroWithdrawalRejected() public {
        vm.prank(attacker);
        (bool ok,) = address(vault).call(abi.encodeCall(vault.withdraw, (0)));
        require(!ok, "zero accepted");
        require(vault.balanceOf(attacker) == 1 ether, "balance changed");
    }
}
